using System.Collections.Generic;

namespace YesSql
{
    /// <summary>
    /// The options of the telemetry of a store.
    /// </summary>
    public sealed class YesSqlTelemetryOptions
    {
        /// <summary>
        /// Gets or sets whether the spans of the database commands include their SQL text, in <c>db.query.text</c>.
        /// </summary>
        /// <remarks>
        /// The statements generated by YesSql are parameterized, but raw SQL fragments given to a query by an application
        /// are included as they are, which is why this is opt-in. The SQL text is never added to metrics.
        /// </remarks>
        /// <value>
        /// The default value is <see langword="false"/>.
        /// </value>
        public bool IncludeQueryText { get; set; }

        /// <summary>
        /// Gets the tags added to all the spans and measurements of the store, such as the name of a tenant.
        /// </summary>
        /// <remarks>
        /// They are recorded on metrics too, so their values should be bounded.
        /// </remarks>
        public IList<KeyValuePair<string, object>> Tags { get; } = new List<KeyValuePair<string, object>>();
    }
}
